/**
 * The panel's Firebase client — the web SDK pointed at the SAME project,
 * database and rules the mobile app uses.
 *
 * Two details are copied from `mobile/lib/firebase.ts` on purpose and must
 * not drift:
 *
 * 1. **The Realtime Database is reached by HOST, not by id.** The project
 *    was provisioned as ENTERPRISE with an explicitly named, REGIONAL
 *    database (`https://<project>-default-rtdb.<region>.firebasedatabase.app`).
 * 2. **Env names are `NEXT_PUBLIC_*`** instead of `EXPO_PUBLIC_*` — same six
 *    values; `.env.local` is generated by prefixing the mobile's `.env`.
 *
 * ## No Firestore here, on purpose
 *
 * The panel used to hold a `Firestore` handle beside the RTDB one and read
 * half its data from each. That split is gone: RTDB is the ONE database the
 * panel and the phone share, and the rules that govern it live in
 * `mobile/database.rules.json`. Keeping a Firestore import here would mean a
 * second, differently-shaped rule set nobody remembers to update — the exact
 * trap this migration exists to close.
 *
 * Client-only module: every import of this file happens from `'use client'`
 * code, so auth never runs during a server render.
 */
import { getApps, initializeApp, type FirebaseApp } from 'firebase/app';
import { connectAuthEmulator, getAuth, type Auth } from 'firebase/auth';
import {
  getDatabase,
  connectDatabaseEmulator,
  type Database,
} from 'firebase/database';

const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,
  /**
   * The Realtime Database's URL, NOT an id — this is the one entry in
   * `FirebaseOptions` that names a *host*.
   *
   * `getDatabase(app, 'default')` does not mean "the database called
   * default": the second argument is parsed as a URL, `'default'` has no
   * host, and `parseRepoInfo` calls `fatal('Cannot parse Firebase url…')` at
   * module import time, before a single screen renders. `getDatabase(app)`
   * with this key absent is no better — the SDK cannot guess the host of a
   * regional database.
   */
  databaseURL: process.env.NEXT_PUBLIC_FIREBASE_DATABASE_URL,
};

if (!firebaseConfig.apiKey || !firebaseConfig.projectId) {
  throw new Error(
    'Missing Firebase environment variables. Copy .env.example (or the mobile ' +
      'app\'s .env) into admin/.env.local with the NEXT_PUBLIC_FIREBASE_* names.'
  );
}

// Guards against double-init when Fast Refresh re-executes the module.
const existing = getApps()[0];
export const app: FirebaseApp = existing ?? initializeApp(firebaseConfig);

/**
 * `getAuth(app)` uses `browserLocalPersistence` on the web automatically, so
 * a signed-in admin survives reloads without any of React Native's
 * persistence gymnastics from the mobile file.
 */
export const auth: Auth = getAuth(app);

/**
 * The Realtime Database handle, created on first use.
 *
 * **Lazy on purpose.** `getDatabase` throws when the URL is missing or
 * unparseable, and this module is imported by every page. Eagerly building
 * the instance would turn one unset env var into "the panel crashes at boot
 * and shows nothing". Deferring it means the pages still render, and the
 * first RTDB operation reports the actual problem instead of taking the
 * whole panel down.
 *
 * `getDatabase` is itself memoised per app instance, so calling this once per
 * operation is free — and it is what makes Fast Refresh safe here, matching
 * the `existing` guard at the top of the file.
 */
let database: Database | null = null;

export function realtime(): Database {
  if (database) return database;

  const url = firebaseConfig.databaseURL;
  if (!url) {
    throw new Error(
      'NEXT_PUBLIC_FIREBASE_DATABASE_URL is not set. The Realtime Database is ' +
        'reached by host, not by id — copy the mobile app\'s .env into ' +
        'admin/.env.local and set it to ' +
        'https://<project>-default-rtdb.<region>.firebasedatabase.app.'
    );
  }

  database = getDatabase(app, url);
  return database;
}

/**
 * Point at the local emulators when NEXT_PUBLIC_FIREBASE_USE_EMULATOR=1
 * (`npm run emulators` in mobile/ starts them). Gated on `!existing` because
 * `connect*Emulator` throws once the instance has made a request, which a
 * Fast Refresh re-run would have done.
 */
if (
  !existing &&
  typeof window !== 'undefined' &&
  process.env.NEXT_PUBLIC_FIREBASE_USE_EMULATOR === '1'
) {
  connectAuthEmulator(auth, 'http://localhost:9099', { disableWarnings: true });
  connectDatabaseEmulator(realtime(), 'localhost', 9000);
  console.log('[firebase] using emulators at localhost');
}